css:
.booking-wrapper {
    border: 1px solid #ddd;
    padding: 20px;
    font-family: Arial, sans-serif;
    max-width: 700px;
}

.booking-header {
    display: flex;
    align-items: center;
    border-bottom: 1px solid #ccc;
    padding-bottom: 10px;
    margin-bottom: 20px;
}

.booking-logo {
    height: 60px;
    margin-right: 15px;
}

.booking-title {
    margin: 0;
    color: #2a9d8f;
}

.booking-subtitle {
    margin: 0;
    font-size: 12px;
    color: #555;
}

.booking-section-title {
    color: #264653;
}

.booking-table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 15px;
}

.booking-table td {
    padding: 8px;
}

.booking-table tr:nth-child(even) {
    background-color: #f8f9fa;
}

.booking-footer {
    margin-top: 30px;
    font-size: 12px;
    color: #777;
}
